const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '木塞拔出过程三阶段：木塞相对瓶口基准的位置' },
      { kind: 'text', payload: 'u = x/h = 0' },
      { kind: 'text', payload: 'u = x/h = 1/2' },
      { kind: 'text', payload: 'u = x/h = 1' },
      { kind: 'text', payload: '瓶口基准线（水平）' },
      { kind: 'text', payload: 'u = 1 时，木塞底部到达瓶口基准线' },
      { kind: 'text', payload: 'x：木塞底部上移量；h：从初始位置到瓶口的位移；三阶段按真实比例：0、h/2、h' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var paths = [];
    var children = [];
    function addPath(id, commands, fill, stroke) {
      paths.push({ id: id, commands: commands });
      var node = { type: 'path', pathId: id, fill: fill };
      if (stroke) { node.stroke = stroke; }
      children.push(node);
    }
    function addLabel(contentId, x, y, hAlign, vAlign, color) {
      children.push({ type: 'label', contentId: contentId, anchor: { x: x, y: y }, hAlign: hAlign, vAlign: vAlign, color: color });
    }
    function corkCommands(cx, bottomY, corkH, topW, botW) {
      var topY = bottomY - corkH;
      var rTop = Math.min(topW, botW) * 0.10;
      var rBot = Math.min(topW, botW) * 0.10;
      var ht = topW / 2;
      var hb = botW / 2;
      return [
        ['M', cx - ht + rTop, topY],
        ['L', cx + ht - rTop, topY],
        ['Q', cx + ht, topY, cx + ht, topY + rTop],
        ['L', cx + hb, bottomY - rBot],
        ['Q', cx + hb, bottomY, cx + hb - rBot, bottomY],
        ['L', cx - hb + rBot, bottomY],
        ['Q', cx - hb, bottomY, cx - hb, bottomY - rBot],
        ['L', cx - ht, topY + rTop],
        ['Q', cx - ht, topY, cx - ht + rTop, topY],
        ['Z']
      ];
    }
    var marginX = Math.max(16, W * 0.04);
    var mouthY = H * 0.55;
    var h = H * 0.26;
    var neckH = h * 1.15;
    var panelW = (W - 2 * marginX) / 3;
    var corkW = Math.min(panelW * 0.22, W * 0.06, h * 0.45);
    var neckW = corkW * 1.28;
    var centers = [marginX + panelW * 0.5, marginX + panelW * 1.5, marginX + panelW * 2.5];
    var uList = [0, 0.5, 1];
    addPath('baseline', [['M', marginX, mouthY], ['L', W - marginX, mouthY]], '#8a9bb0', { width: 1.6, dash: [6, 5] });
    var i;
    for (i = 0; i < 3; i = i + 1) {
      var cx = centers[i];
      addPath('neck_l_' + i, [['M', cx - neckW / 2, mouthY], ['L', cx - neckW / 2, mouthY + neckH]], '#5b6b7f', { width: 2 });
      addPath('neck_r_' + i, [['M', cx + neckW / 2, mouthY], ['L', cx + neckW / 2, mouthY + neckH]], '#5b6b7f', { width: 2 });
      addPath('neck_b_' + i, [['M', cx - neckW / 2, mouthY + neckH], ['L', cx + neckW / 2, mouthY + neckH]], '#5b6b7f', { width: 2 });
      var lip = neckW * 0.18;
      addPath('lip_l_' + i, [['M', cx - neckW / 2 - lip, mouthY], ['L', cx - neckW / 2, mouthY]], '#5b6b7f', { width: 2 });
      addPath('lip_r_' + i, [['M', cx + neckW / 2, mouthY], ['L', cx + neckW / 2 + lip, mouthY]], '#5b6b7f', { width: 2 });
      var u = uList[i];
      var bottomY = mouthY + h * (1 - u);
      var topY = bottomY - h;
      var topW = corkW;
      var botW = corkW * 0.86;
      addPath('cork_' + i, corkCommands(cx, bottomY, h, topW, botW), '#c9a36a', { width: 2, join: 'round' });
      addPath('grain1_' + i, [['M', cx - topW * 0.18, topY + h * 0.18], ['Q', cx - botW * 0.10, topY + h * 0.52, cx - botW * 0.20, bottomY - h * 0.16]], '#a57c47', { width: 1.2, cap: 'round' });
      addPath('grain2_' + i, [['M', cx + topW * 0.10, topY + h * 0.22], ['Q', cx + botW * 0.04, topY + h * 0.55, cx + botW * 0.12, bottomY - h * 0.18]], '#a57c47', { width: 1.2, cap: 'round' });
    }
    addLabel(metrics[0].contentId, W / 2, H * 0.05, 'center', 'top', '#1f2d3d');
    for (i = 0; i < 3; i = i + 1) {
      addLabel(metrics[i + 1].contentId, centers[i], H * 0.87, 'center', 'top', '#1f2d3d');
    }
    addLabel(metrics[4].contentId, marginX, mouthY - H * 0.025, 'left', 'bottom', '#5b6b7f');
    addLabel(metrics[5].contentId, W / 2, H * 0.915, 'center', 'top', '#1f2d3d');
    addLabel(metrics[6].contentId, W / 2, H * 0.985, 'center', 'bottom', '#1f2d3d');
    return {
      schemaVersion: 1,
      sceneId: 'stopper-three-stages',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: { type: 'group', children: children }
    };
  }
};
